package ro.leo.visual;
import ro.leo.i18n.L;
import android.app.Activity;import android.content.*;import android.graphics.*;import android.os.*;import android.provider.Settings;import android.view.*;import java.text.SimpleDateFormat;import java.util.*;import org.json.*;

/** Five keypad tabs, using the same persistent alarm/timer backend as before. */
public final class ClockActivity extends Activity {
 private final Handler handler=new Handler();private final ArrayList<Long> laps=new ArrayList<Long>();private final ArrayList<String> zones=new ArrayList<String>();
 private static final String[] CITY=L.array(new String[]{"București","Londra","New York","Tokyo","Paris","Berlin","Chișinău","Dubai","Los Angeles","Sydney","Delhi","UTC"});
 private static final String[] ZONE={"Europe/Bucharest","Europe/London","America/New_York","Asia/Tokyo","Europe/Paris","Europe/Berlin","Europe/Chisinau","Asia/Dubai","America/Los_Angeles","Australia/Sydney","Asia/Kolkata","UTC"};
 private final String[] tabs={L.t("Ora"),L.t("Alarme"),L.t("Glob"),"Timer",L.t("Crono")};
 private Appearance.Palette palette;private Face face;private int page,selected,boot;private boolean running,visible;private long accumulated,started,paused;private JSONArray alarms=new JSONArray();
 private final Runnable tick=new Runnable(){public void run(){if(!visible)return;face.invalidate();handler.postDelayed(this,page==4&&running?100:1000);}};
 public void onCreate(Bundle state){super.onCreate(state);palette=Appearance.palette(this);getWindow().setStatusBarColor(palette.bar);boot=Settings.Global.getInt(getContentResolver(),Settings.Global.BOOT_COUNT,-1);SharedPreferences p=getSharedPreferences("clock",0);accumulated=p.getLong("elapsed",0);started=p.getLong("started",0);running=p.getBoolean("running",false)&&boot>=0&&p.getInt("boot",-2)==boot&&started<=SystemClock.elapsedRealtime();page=Math.max(0,Math.min(4,p.getInt("tab",p.getBoolean("stopwatch",false)?4:0)));paused=p.getLong("timer-paused",0);
  for(String s:p.getString("laps","").split(","))try{if(laps.size()<50)laps.add(Long.parseLong(s));}catch(NumberFormatException ignored){}Set<String> valid=new HashSet<String>(Arrays.asList(TimeZone.getAvailableIDs()));for(String z:p.getString("zones","Europe/Bucharest,Europe/London,America/New_York,Asia/Tokyo").split(","))if(valid.contains(z)&&!zones.contains(z)&&zones.size()<8)zones.add(z);if(getIntent().hasExtra("tab"))page=Math.max(0,Math.min(4,getIntent().getIntExtra("tab",0)));face=new Face();setContentView(face);}
 protected void onResume(){super.onResume();visible=true;reload();if(AlarmScheduler.state(this).getBoolean("timer",false))paused=0;handler.removeCallbacks(tick);handler.post(tick);}
 protected void onPause(){visible=false;handler.removeCallbacks(tick);save();super.onPause();}protected void onDestroy(){handler.removeCallbacksAndMessages(null);super.onDestroy();}
 private void reload(){try{alarms=AlarmScheduler.alarms(this);}catch(RuntimeException e){alarms=new JSONArray();}selected=Math.max(0,Math.min(selected,Math.max(0,(page==1?alarms.length():zones.size())-1)));}
 private long elapsed(){return accumulated+(running?SystemClock.elapsedRealtime()-started:0);}
 private void save(){if(running){accumulated=elapsed();started=SystemClock.elapsedRealtime();}StringBuilder s=new StringBuilder();for(Long lap:laps){if(s.length()>0)s.append(',');s.append(lap);}getSharedPreferences("clock",0).edit().putLong("elapsed",accumulated).putLong("started",started).putBoolean("running",running).putInt("boot",boot).putInt("tab",page).putString("laps",s.toString()).putString("zones",android.text.TextUtils.join(",",zones)).putLong("timer-paused",paused).apply();}
 private void changed(){save();reload();handler.removeCallbacks(tick);if(visible)handler.post(tick);}
 private void options(String title,String[] items,KeypadDialog.Action action){new KeypadDialog(this,title,items,action).show();}
 private void editAlarm(boolean create){Intent i=new Intent(this,AlarmsActivity.class);if(create)i.putExtra("new",true);else if(alarms.optJSONObject(selected)!=null)i.putExtra("edit_id",alarms.optJSONObject(selected).optInt("id"));startActivity(i);}
 private void toggleAlarm(){JSONObject a=alarms.optJSONObject(selected);if(a==null){editAlarm(true);return;}try{AlarmScheduler.save(this,a.getInt("id"),a.getInt("hour"),a.getInt("minute"),a.optString("label"),a.optBoolean("daily"),!a.optBoolean("enabled"));changed();}catch(Exception e){android.widget.Toast.makeText(this,L.t("Alarma nu poate fi modificată"),0).show();}}
 private void timer(){boolean active=AlarmScheduler.state(this).getBoolean("timer",false);if(active){long remaining=AlarmScheduler.remaining(this);if(remaining>0){paused=remaining;AlarmScheduler.cancelTimer(this);}}else if(paused>0){AlarmScheduler.timer(this,paused);paused=0;}else startActivity(new Intent(this,TimerActivity.class));changed();}
 private void menu(){if(page==1){options(L.t("Alarme"),new String[]{L.t("Alarmă nouă"),L.t("Editează selecția"),L.t("Gestionează alarmele"),L.t("Amânare · ")+getSharedPreferences("clock",0).getInt("snooze",10)+" min"},new KeypadDialog.Action(){public void select(int i){if(i==3)options(L.t("Durata amânării"),new String[]{L.t("5 minute"),L.t("10 minute"),L.t("15 minute")},new KeypadDialog.Action(){public void select(int n){getSharedPreferences("clock",0).edit().putInt("snooze",new int[]{5,10,15}[n]).apply();}});else if(i==2)startActivity(new Intent(ClockActivity.this,AlarmsActivity.class));else editAlarm(i==0);}});}else if(page==2){options(L.t("Ora pe glob"),new String[]{L.t("Adaugă oraș"),L.t("Elimină orașul selectat"),L.t("Mută orașul în primul loc")},new KeypadDialog.Action(){public void select(int i){if(i==2){if(!zones.isEmpty()){String z=zones.remove(selected);zones.add(0,z);selected=0;}changed();}else if(i==1){if(!zones.isEmpty())zones.remove(selected);changed();}else options(L.t("Alege orașul"),CITY,new KeypadDialog.Action(){public void select(int n){if(!zones.contains(ZONE[n])&&zones.size()<8)zones.add(ZONE[n]);else android.widget.Toast.makeText(ClockActivity.this,L.t("Maximum 8 orașe; fără duplicate"),0).show();changed();}});}});}else if(page==3){options(L.t("Temporizator"),new String[]{L.t("Durată personalizată"),L.t("1 minut"),L.t("5 minute"),L.t("10 minute"),L.t("25 minute"),L.t("Oprește / resetează")},new KeypadDialog.Action(){public void select(int i){if(i==5){AlarmScheduler.cancelTimer(ClockActivity.this);paused=0;}else if(i==0)startActivity(new Intent(ClockActivity.this,TimerActivity.class));else{AlarmScheduler.timer(ClockActivity.this,new long[]{0,60000,300000,600000,1500000}[i]);paused=0;}changed();}});}else if(page==4){options(L.t("Cronometru"),new String[]{running?L.t("Înregistrează tură"):L.t("Resetează"),L.t("Vezi turele")},new KeypadDialog.Action(){public void select(int i){if(i==0){if(running){if(laps.size()<50)laps.add(elapsed());}else{accumulated=0;laps.clear();}changed();}else{String[] rows=new String[laps.size()];for(int n=0;n<rows.length;n++)rows[n]="T"+(n+1)+" · "+duration(laps.get(n),true);if(rows.length==0)rows=new String[]{L.t("Nicio tură înregistrată")};options(L.t("Ture"),rows,new KeypadDialog.Action(){public void select(int n){}});}}});}else options(L.t("Ceas"),new String[]{L.t("Alarme"),L.t("Ora pe glob"),L.t("Temporizator"),L.t("Cronometru"),L.t("Dată și fus orar"),L.t("Ceas de birou")},new KeypadDialog.Action(){public void select(int i){if(i==5)startActivity(new Intent(ClockActivity.this,DeskClockActivity.class));else if(i==4)startActivity(new Intent(ClockActivity.this,DateTimeSettingsActivity.class));else{page=i+1;selected=0;changed();}}});}
 public boolean dispatchKeyEvent(KeyEvent e){if(LeoActivity.isJackNavigationNoise(e))return true;return super.dispatchKeyEvent(e);}
 public boolean onKeyDown(int key,KeyEvent e){if(key==KeyEvent.KEYCODE_BACK){if(e.getRepeatCount()==0)finish();return true;}if(key==KeyEvent.KEYCODE_DPAD_LEFT||key==KeyEvent.KEYCODE_DPAD_RIGHT){if(e.getRepeatCount()==0){page=(page+(key==KeyEvent.KEYCODE_DPAD_RIGHT?1:4))%5;selected=0;changed();}return true;}if(key==KeyEvent.KEYCODE_DPAD_UP||key==KeyEvent.KEYCODE_DPAD_DOWN){int count=page==1?alarms.length():page==2?zones.size():0;selected=Math.max(0,Math.min(Math.max(0,count-1),selected+(key==KeyEvent.KEYCODE_DPAD_DOWN?1:-1)));face.invalidate();return true;}if(key==KeyEvent.KEYCODE_MENU){if(e.getRepeatCount()==0)menu();return true;}if(key==KeyEvent.KEYCODE_DPAD_CENTER||key==KeyEvent.KEYCODE_ENTER){if(e.getRepeatCount()==0){if(page==1)toggleAlarm();else if(page==2)menu();else if(page==3)timer();else if(page==4){if(running){accumulated=elapsed();running=false;}else{started=SystemClock.elapsedRealtime();running=true;}changed();}else{page=1;changed();}}return true;}return super.onKeyDown(key,e);}
 static String duration(long ms,boolean tenths){long s=Math.max(0,ms)/1000;return String.format(Locale.ROOT,"%02d:%02d:%02d",s/3600,s/60%60,s%60)+(tenths?"."+(Math.max(0,ms)/100%10):"");}
 private String fmt(String pattern,Date now,TimeZone zone){SimpleDateFormat f=new SimpleDateFormat(pattern,L.locale());f.setTimeZone(zone);return f.format(now);}
 private String zoneName(String z){for(int i=0;i<ZONE.length;i++)if(ZONE[i].equals(z))return CITY[i];return z.substring(z.lastIndexOf('/')+1).replace('_',' ');}
 private String nextAlarm(){long next=Long.MAX_VALUE;for(int i=0;i<alarms.length();i++){JSONObject a=alarms.optJSONObject(i);if(a!=null&&a.optBoolean("enabled"))try{next=Math.min(next,AlarmScheduler.next(System.currentTimeMillis(),a));}catch(RuntimeException ignored){}}return next==Long.MAX_VALUE?L.t("Nicio alarmă activă"):L.t("Alarmă · ")+fmt("EEE HH:mm",new Date(next),TimeZone.getDefault());}
 private final class Face extends View {
  final Paint p=new Paint(3);Face(){super(ClockActivity.this);setFocusable(true);requestFocus();}public boolean isOpaque(){return true;}
  void text(Canvas c,String s,int x,int y,int size,int color,Paint.Align align){p.setStyle(Paint.Style.FILL);p.setTextSize(size);p.setColor(color);p.setTextAlign(align);while(p.measureText(s)>220&&p.getTextSize()>9)p.setTextSize(p.getTextSize()-1);c.drawText(s,x,y,p);}
  void card(Canvas c,int y,int h,boolean focus){p.setStyle(Paint.Style.FILL);p.setColor(focus?Appearance.mix(palette.card,palette.accent,.2f):palette.card);c.drawRoundRect(8,y,232,y+h,5,5,p);if(focus){p.setStyle(Paint.Style.STROKE);p.setColor(palette.accent);p.setStrokeWidth(1);c.drawRoundRect(8,y,232,y+h,5,5,p);p.setStyle(Paint.Style.FILL);}}
  protected void onDraw(Canvas c){c.save();c.scale(getWidth()/240f,getHeight()/302f);c.drawColor(palette.background);UiChrome.header(c,L.t("Ceas Leo"),palette,p);for(int i=0;i<5;i++){if(i==page){p.setColor(palette.card);c.drawRect(i*48,34,i*48+48,58,p);p.setColor(palette.accent);c.drawRect(i*48,57,i*48+48,59,p);}text(c,tabs[i],24+i*48,50,11,i==page?palette.accent:Color.WHITE,Paint.Align.CENTER);}Date now=new Date();TimeZone local=TimeZone.getDefault();
   if(page==0){card(c,72,111,false);text(c,fmt("HH:mm:ss",now,local),120,117,37,Color.WHITE,Paint.Align.CENTER);text(c,fmt("EEEE, d MMM",now,local),120,145,16,palette.accent,Paint.Align.CENTER);text(c,fmt("yyyy · z",now,local),120,167,13,0xffbfc2d4,Paint.Align.CENTER);card(c,194,49,false);text(c,nextAlarm(),120,223,14,Color.WHITE,Paint.Align.CENTER);Calendar cal=Calendar.getInstance();text(c,L.t("Săptămâna ")+cal.get(Calendar.WEEK_OF_YEAR)+L.t(" · ziua ")+cal.get(Calendar.DAY_OF_YEAR),120,262,12,palette.accent,Paint.Align.CENTER);}
   else if(page==1){if(alarms.length()==0){text(c,L.t("Nicio alarmă"),120,141,23,Color.WHITE,Paint.Align.CENTER);text(c,L.t("Opțiuni → Alarmă nouă"),120,170,13,palette.accent,Paint.Align.CENTER);}int first=Math.max(0,selected-2);for(int i=first;i<Math.min(alarms.length(),first+3);i++){JSONObject a=alarms.optJSONObject(i);int y=72+(i-first)*59;card(c,y,52,i==selected);text(c,String.format(Locale.ROOT,"%02d:%02d",a.optInt("hour"),a.optInt("minute")),18,y+25,24,Color.WHITE,Paint.Align.LEFT);text(c,a.optBoolean("enabled")?"ON":"OFF",216,y+24,13,a.optBoolean("enabled")?0xff63e0b9:0xff9b9db2,Paint.Align.RIGHT);text(c,a.optString("label",L.t("Alarmă"))+" · "+AlarmScheduler.daysLabel(a),18,y+43,11,palette.accent,Paint.Align.LEFT);}text(c,alarms.length()+L.t(" alarme · OK: activare"),120,264,12,palette.accent,Paint.Align.CENTER);}
   else if(page==2){int first=Math.max(0,selected-2);for(int i=first;i<Math.min(zones.size(),first+3);i++){String z=zones.get(i);TimeZone zone=TimeZone.getTimeZone(z);int y=72+(i-first)*59;card(c,y,52,i==selected);text(c,zoneName(z),18,y+20,15,Color.WHITE,Paint.Align.LEFT);text(c,fmt("HH:mm",now,zone),220,y+24,23,palette.accent,Paint.Align.RIGHT);text(c,fmt("EEE, d MMM · Z",now,zone),18,y+41,11,0xffbfc2d4,Paint.Align.LEFT);}text(c,zones.size()+L.t(" / 8 orașe · fusuri cu DST"),120,264,12,palette.accent,Paint.Align.CENTER);}
   else if(page==3){boolean active=AlarmScheduler.state(ClockActivity.this).getBoolean("timer",false);long value=active?AlarmScheduler.remaining(ClockActivity.this):paused;card(c,80,127,false);text(c,duration(value,false),120,133,35,Color.WHITE,Paint.Align.CENTER);text(c,active?L.t("Numără invers"):paused>0?L.t("În pauză"):L.t("Alege durata"),120,164,15,palette.accent,Paint.Align.CENTER);text(c,active?L.t("Alarma sună și după Home"):L.t("Presetări din Opțiuni"),120,233,13,0xffbfc2d4,Paint.Align.CENTER);}
   else{card(c,76,87,false);text(c,duration(elapsed(),true),120,115,31,Color.WHITE,Paint.Align.CENTER);text(c,running?L.t("În mers"):accumulated>0?L.t("În pauză"):L.t("Pregătit"),120,143,13,palette.accent,Paint.Align.CENTER);int first=Math.max(0,laps.size()-3);for(int i=first;i<laps.size();i++){text(c,L.t("Tura ")+(i+1),14,191+(i-first)*26,13,Color.WHITE,Paint.Align.LEFT);text(c,duration(laps.get(i),true),225,191+(i-first)*26,14,palette.accent,Paint.Align.RIGHT);}}
   p.setColor(palette.bar);c.drawRect(0,277,240,302,p);text(c,L.t("Opțiuni"),7,294,11,Color.WHITE,Paint.Align.LEFT);String action=page==0?L.t("Alarme"):page==1?"ON / OFF":page==2?L.t("Orașe"):page==3?(AlarmScheduler.state(ClockActivity.this).getBoolean("timer",false)?L.t("Pauză"):paused>0?L.t("Continuă"):L.t("Durată")):running?L.t("Pauză"):"Start";text(c,action,120,294,12,palette.accent,Paint.Align.CENTER);text(c,L.t("Înapoi"),233,294,11,Color.WHITE,Paint.Align.RIGHT);c.restore();}
 }
}
